-- Completed years since the first contract start (service is derived from contracts, DATE_START_SERVICE is blank). Columns: ten_y, n
SELECT TRUNC(MONTHS_BETWEEN(DATE '{ASOF}', fs.FS)/12) TEN_Y, COUNT(*) N FROM (SELECT STAFF_ID, MIN(START_DATE) FS FROM {P}PS_STAFF_CONTRACT GROUP BY STAFF_ID) fs WHERE fs.STAFF_ID IN (SELECT STAFF_ID FROM {P}PS_STAFF_CONTRACT WHERE STATUS='A' AND CURRENT_CONTRACT='Y') GROUP BY TRUNC(MONTHS_BETWEEN(DATE '{ASOF}', fs.FS)/12) ORDER BY 1
